<script setup>
import {ref,onMounted} from 'vue';import PageHeader from '../../components/student/PageHeader.vue';import {studentApi} from '../../services/studentApi'
const days=ref([]),classes=ref({}),loading=ref(true),error=ref('');onMounted(async()=>{try{const r=await studentApi.getTimetable();days.value=r.data?.days||[];classes.value=r.data?.classes||{}}catch(e){error.value=e.message}finally{loading.value=false}})
</script>
<template><div><PageHeader title="Timetable" subtitle="Your actual booked schedule."/><p v-if="loading">Loading timetable...</p><p v-else-if="error" class="text-red-500">{{error}}</p><div v-else class="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4"><div v-for="day in days" :key="day" class="card p-5"><h3 class="font-display font-bold mb-3">{{day}}</h3><div v-if="!(classes[day]||[]).length" class="text-sm text-slate-500">No session.</div><div v-for="c in classes[day]" :key="c.session_id" class="rounded-xl bg-slate-50 dark:bg-white/5 p-3 mb-2"><p class="font-semibold">{{c.subject}}</p><p class="text-sm text-slate-500">{{c.time}}</p><p class="text-xs text-slate-500">{{c.tutor}} · {{c.status}}</p></div></div></div></div></template>
